package com.mercan.fuzulplanim.data

import android.content.Context
import org.json.JSONArray
import org.json.JSONObject
import java.time.LocalDate
import java.time.LocalDateTime
import java.time.YearMonth
import java.time.temporal.ChronoUnit
import java.util.UUID

class FinanceRepository(private val context: Context) {
    val dao = FinanceDatabase.get(context).dao()
    val fixedExpenses=dao.observeFixedExpenses(); val installments=dao.observeInstallments(); val assets=dao.observeAssets(); val transactions=dao.observeTransactions(); val monthlyPlan=dao.observeMonthlyPlan(); val contract=dao.observeContract(); val cards=dao.observeCards(); val imports=dao.observeImports()

    suspend fun saveFixedExpense(x:FixedExpenseEntity)=dao.upsertFixedExpense(x); suspend fun deleteFixedExpense(x:FixedExpenseEntity)=dao.deleteFixedExpense(x)
    suspend fun saveInstallment(x:InstallmentEntity)=dao.upsertInstallment(x); suspend fun deleteInstallment(x:InstallmentEntity)=dao.deleteInstallment(x)
    suspend fun saveAsset(x:AssetEntity)=dao.upsertAsset(x); suspend fun deleteAsset(x:AssetEntity)=dao.deleteAsset(x)
    suspend fun saveCard(x:CardEntity)=dao.upsertCard(x); suspend fun deleteCard(x:CardEntity)=dao.deleteCard(x)
    suspend fun saveMonthlyPlan(x:MonthlyPlanEntity)=dao.upsertMonthlyPlan(x); suspend fun saveContract(x:FuzulContractEntity)=dao.upsertContract(x)

    suspend fun replaceBudgetFromWorkbook(fixed:List<FixedExpenseEntity>,inst:List<InstallmentEntity>,months:List<MonthlyPlanEntity>,contract:FuzulContractEntity?,tx:List<TransactionEntity>,cards:List<CardEntity>,sourceName:String){
        dao.clearFixedExpenses();dao.clearInstallments();dao.clearMonthlyPlans();dao.clearContract();dao.clearTransactions();dao.clearCards()
        if(fixed.isNotEmpty())dao.upsertFixedExpenses(fixed);if(inst.isNotEmpty())dao.upsertInstallments(inst);if(months.isNotEmpty())dao.upsertMonthlyPlans(months);if(contract!=null)dao.upsertContract(contract);if(tx.isNotEmpty())dao.insertTransactions(tx);if(cards.isNotEmpty())dao.upsertCards(cards)
        dao.upsertImport(ImportBatchEntity(UUID.randomUUID().toString(),sourceName,"XLSX",LocalDateTime.now().toString(),"BÜTÇE EXCEL",fixed.size+inst.size+months.size+tx.size,fixed.size+inst.size+months.size+tx.size,"Başarılı","SABIT_GİDER, Taksit Takibi, Aylık Plan, FUZUL_SOZLESME ve Tüm İşlemler aktarıldı."))
    }
    suspend fun importTransactions(rows:List<TransactionEntity>,sourceName:String,fileType:String,note:String=""):Int{val r=dao.insertTransactions(rows);val n=r.count{it!=-1L};dao.upsertImport(ImportBatchEntity(UUID.randomUUID().toString(),sourceName,fileType,LocalDateTime.now().toString(),"EKSTRE / HESAP HAREKETİ",rows.size,n,if(n>0)"Başarılı" else "Yeni kayıt yok",note));return n}

    fun installmentLoad(month:String,items:List<InstallmentEntity>):Double{val ym=runCatching{YearMonth.parse(month)}.getOrNull()?:return 0.0;return items.filter{it.active}.sumOf{i->val s=runCatching{YearMonth.parse(i.nextMonth)}.getOrNull();val e=runCatching{YearMonth.parse(i.endMonth)}.getOrNull();if(s!=null&&e!=null&&!ym.isBefore(s)&&!ym.isAfter(e))i.monthlyAmount else 0.0}}
    fun fixedDelta(month:String,group:String,fixed:List<FixedExpenseEntity>):Double{val ym=runCatching{YearMonth.parse(month)}.getOrNull()?:return 0.0;return fixed.filter{it.budgetGroup==group}.sumOf{f->val s=f.startMonth.takeIf{it.isNotBlank()}?.let{runCatching{YearMonth.parse(it)}.getOrNull()};val e=f.endMonth.takeIf{it.isNotBlank()}?.let{runCatching{YearMonth.parse(it)}.getOrNull()};val ok=(s==null||!ym.isBefore(s))&&(e==null||!ym.isAfter(e));if(!ok)0.0 else (if(f.active)adjustedAmount(f,ym,s) else 0.0)-f.baselineAmount}}
    private fun adjustedAmount(f:FixedExpenseEntity,ym:YearMonth,start:YearMonth?):Double{if(!f.inflationLinked||f.annualInflationPct==0.0||start==null)return f.amount;val months=ChronoUnit.MONTHS.between(start,ym).coerceAtLeast(0);val monthly=Math.pow(1.0+f.annualInflationPct/100.0,1.0/12.0)-1.0;return f.amount*Math.pow(1.0+monthly,months.toDouble())}
    fun planExpense(m:MonthlyPlanEntity,fixed:List<FixedExpenseEntity>,inst:List<InstallmentEntity>):Double{val bills=m.billsSnapshot+fixedDelta(m.month,"bills",fixed);val education=m.educationSnapshot+fixedDelta(m.month,"education",fixed);val transport=m.transport+fixedDelta(m.month,"transport",fixed);val other=m.otherSnapshot+fixedDelta(m.month,"other",fixed);val living=m.living+fixedDelta(m.month,"living",fixed);val cards=installmentLoad(m.month,inst).let{if(inst.isEmpty())m.cardsSnapshot else it};return m.orgFee+bills+living+cards+education+transport+other}
    fun planNet(m:MonthlyPlanEntity,fixed:List<FixedExpenseEntity>,inst:List<InstallmentEntity>)=m.meteIncome+m.esmaIncome+m.otherIncome-planExpense(m,fixed,inst)-m.fuzulPayment
    fun currentAssetValue(a:AssetEntity):Double{if(a.type!="Vadeli Hesap")return a.currentValue;val s=runCatching{LocalDate.parse(a.startDate)}.getOrNull();val e=runCatching{LocalDate.parse(a.maturityDate)}.getOrNull();if(s==null||e==null||!e.isAfter(s))return a.currentValue.takeIf{it>0}?:a.principal;val days=ChronoUnit.DAYS.between(s,e).toDouble();val gross=a.principal*(a.annualRatePct/100.0)*days/365.0;return a.principal+gross-gross*(a.withholdingPct/100.0)}

    suspend fun exportBackupJson():String{val root=JSONObject();root.put("version",2);root.put("exportedAt",LocalDateTime.now().toString());root.put("fixedExpenses",JSONArray(dao.getFixedExpenses().map(::fixedToJson)));root.put("installments",JSONArray(dao.getInstallments().map(::installmentToJson)));root.put("assets",JSONArray(dao.getAssets().map(::assetToJson)));root.put("transactions",JSONArray(dao.getTransactions().map(::txToJson)));root.put("monthlyPlan",JSONArray(dao.getMonthlyPlan().map(::monthToJson)));root.put("cards",JSONArray(dao.getCards().map(::cardToJson)));dao.getContract()?.let{root.put("contract",contractToJson(it))};return root.toString(2)}
    suspend fun restoreBackupJson(raw:String){val root=JSONObject(raw);dao.clearFixedExpenses();dao.clearInstallments();dao.clearAssets();dao.clearTransactions();dao.clearMonthlyPlans();dao.clearCards();dao.clearContract();jsonArray(root,"fixedExpenses").map(::jsonToFixed).takeIf{it.isNotEmpty()}?.let{dao.upsertFixedExpenses(it)};jsonArray(root,"installments").map(::jsonToInstallment).takeIf{it.isNotEmpty()}?.let{dao.upsertInstallments(it)};jsonArray(root,"assets").map(::jsonToAsset).takeIf{it.isNotEmpty()}?.let{dao.upsertAssets(it)};jsonArray(root,"transactions").map(::jsonToTx).takeIf{it.isNotEmpty()}?.let{dao.insertTransactions(it)};jsonArray(root,"monthlyPlan").map(::jsonToMonth).takeIf{it.isNotEmpty()}?.let{dao.upsertMonthlyPlans(it)};jsonArray(root,"cards").map(::jsonToCard).takeIf{it.isNotEmpty()}?.let{dao.upsertCards(it)};root.optJSONObject("contract")?.let{dao.upsertContract(jsonToContract(it))};dao.upsertImport(ImportBatchEntity(UUID.randomUUID().toString(),"Yedek","JSON",LocalDateTime.now().toString(),"UYGULAMA YEDEĞİ",0,0,"Başarılı","Yerel yedek geri yüklendi"))}
    private fun jsonArray(r:JSONObject,k:String):List<JSONObject>{val a=r.optJSONArray(k)?:return emptyList();return(0 until a.length()).mapNotNull{a.optJSONObject(it)}}
    private fun fixedToJson(x:FixedExpenseEntity)=JSONObject().apply{put("id",x.id);put("name",x.name);put("category",x.category);put("amount",x.amount);put("baselineAmount",x.baselineAmount);put("paymentSource",x.paymentSource);put("budgetGroup",x.budgetGroup);put("frequency",x.frequency);put("startMonth",x.startMonth);put("endMonth",x.endMonth);put("dayOfMonth",x.dayOfMonth);put("inflationLinked",x.inflationLinked);put("annualInflationPct",x.annualInflationPct);put("active",x.active);put("imported",x.imported)}
    private fun installmentToJson(x:InstallmentEntity)=JSONObject().apply{put("id",x.id);put("bank",x.bank);put("merchant",x.merchant);put("category",x.category);put("totalAmount",x.totalAmount);put("monthlyAmount",x.monthlyAmount);put("totalInstallments",x.totalInstallments);put("paidInstallments",x.paidInstallments);put("remainingDebt",x.remainingDebt);put("nextMonth",x.nextMonth);put("endMonth",x.endMonth);put("active",x.active);put("imported",x.imported)}
    private fun assetToJson(x:AssetEntity)=JSONObject().apply{put("id",x.id);put("type",x.type);put("institution",x.institution);put("name",x.name);put("principal",x.principal);put("currentValue",x.currentValue);put("annualRatePct",x.annualRatePct);put("withholdingPct",x.withholdingPct);put("startDate",x.startDate);put("maturityDate",x.maturityDate);put("note",x.note)}
    private fun txToJson(x:TransactionEntity)=JSONObject().apply{put("id",x.id);put("date",x.date);put("source",x.source);put("description",x.description);put("amount",x.amount);put("category",x.category);put("subCategory",x.subCategory);put("includedInBudget",x.includedInBudget);put("transactionType",x.transactionType);put("sourceFile",x.sourceFile);put("note",x.note)}
    private fun monthToJson(x:MonthlyPlanEntity)=JSONObject().apply{put("month",x.month);put("meteIncome",x.meteIncome);put("esmaIncome",x.esmaIncome);put("otherIncome",x.otherIncome);put("orgFee",x.orgFee);put("billsSnapshot",x.billsSnapshot);put("living",x.living);put("cardsSnapshot",x.cardsSnapshot);put("educationSnapshot",x.educationSnapshot);put("transport",x.transport);put("otherSnapshot",x.otherSnapshot);put("fuzulPayment",x.fuzulPayment);put("fuzulPaid",x.fuzulPaid)}
    private fun cardToJson(x:CardEntity)=JSONObject().apply{put("id",x.id);put("bank",x.bank);put("name",x.name);put("last4",x.last4);put("statementBalance",x.statementBalance);put("availableLimit",x.availableLimit);put("dueDate",x.dueDate)}
    private fun contractToJson(x:FuzulContractEntity)=JSONObject().apply{put("fundingType",x.fundingType);put("amount",x.amount);put("downPayment",x.downPayment);put("organizationFee",x.organizationFee);put("contractDate",x.contractDate);put("allocationPeriod",x.allocationPeriod);put("allocationDate",x.allocationDate);put("installmentCount",x.installmentCount);put("lastPaymentDate",x.lastPaymentDate);put("openingCash",x.openingCash)}
    private fun jsonToFixed(o:JSONObject)=FixedExpenseEntity(o.optString("id"),o.optString("name"),o.optString("category"),o.optDouble("amount"),o.optDouble("baselineAmount"),o.optString("paymentSource"),o.optString("budgetGroup","bills"),o.optString("frequency","MONTHLY"),o.optString("startMonth"),o.optString("endMonth"),o.optInt("dayOfMonth",1),o.optBoolean("inflationLinked"),o.optDouble("annualInflationPct"),o.optBoolean("active",true),o.optBoolean("imported"))
    private fun jsonToInstallment(o:JSONObject)=InstallmentEntity(o.optString("id"),o.optString("bank"),o.optString("merchant"),o.optString("category"),o.optDouble("totalAmount"),o.optDouble("monthlyAmount"),o.optInt("totalInstallments"),o.optInt("paidInstallments"),o.optDouble("remainingDebt"),o.optString("nextMonth"),o.optString("endMonth"),o.optBoolean("active",true),o.optBoolean("imported"))
    private fun jsonToAsset(o:JSONObject)=AssetEntity(o.optString("id"),o.optString("type"),o.optString("institution"),o.optString("name"),o.optDouble("principal"),o.optDouble("currentValue"),o.optDouble("annualRatePct"),o.optDouble("withholdingPct"),o.optString("startDate"),o.optString("maturityDate"),o.optString("note"))
    private fun jsonToTx(o:JSONObject)=TransactionEntity(o.optString("id"),o.optString("date"),o.optString("source"),o.optString("description"),o.optDouble("amount"),o.optString("category"),o.optString("subCategory"),o.optBoolean("includedInBudget",true),o.optString("transactionType","EXPENSE"),o.optString("sourceFile"),o.optString("note"))
    private fun jsonToMonth(o:JSONObject)=MonthlyPlanEntity(o.optString("month"),o.optDouble("meteIncome"),o.optDouble("esmaIncome"),o.optDouble("otherIncome"),o.optDouble("orgFee"),o.optDouble("billsSnapshot"),o.optDouble("living"),o.optDouble("cardsSnapshot"),o.optDouble("educationSnapshot"),o.optDouble("transport"),o.optDouble("otherSnapshot"),o.optDouble("fuzulPayment"),o.optBoolean("fuzulPaid"))
    private fun jsonToCard(o:JSONObject)=CardEntity(o.optString("id"),o.optString("bank"),o.optString("name"),o.optString("last4"),o.optDouble("statementBalance"),o.optDouble("availableLimit"),o.optString("dueDate"))
    private fun jsonToContract(o:JSONObject)=FuzulContractEntity(1,o.optString("fundingType"),o.optDouble("amount"),o.optDouble("downPayment"),o.optDouble("organizationFee"),o.optString("contractDate"),o.optInt("allocationPeriod"),o.optString("allocationDate"),o.optInt("installmentCount"),o.optString("lastPaymentDate"),o.optDouble("openingCash"))
}
